import { Contract, GlobalState, abimethod, uint64, Txn, Global, Uint64, Bytes, assert, Account, itxn, clone } from '@algorandfoundation/algorand-typescript'

export class JokePayPerCall extends Contract {
  owner = GlobalState<Account>({ key: 'o' })
  pricePerCall = GlobalState<uint64>({ key: 'p' })
  totalCalls = GlobalState<uint64>({ key: 'tc' })
  totalEarned = GlobalState<uint64>({ key: 'te' })

  public createApplication(): void {
    this.owner.value = Txn.sender
    this.pricePerCall.value = Uint64(5000)
    this.totalCalls.value = Uint64(0)
    this.totalEarned.value = Uint64(0)
  }

  @abimethod()
  public initialize(price: uint64): void {
    assert(Txn.sender === this.owner.value, 'Only owner can initialize')
    this.pricePerCall.value = price
  }

  @abimethod()
  public record_payment(caller: Account, amount: uint64): void {
    // In a production x402 flow, this is typically called by the facilitator 
    // or the service backend after verifying the on-chain transfer.
    assert(amount >= this.pricePerCall.value, 'Insufficient payment amount')

    this.totalCalls.value = this.totalCalls.value + Uint64(1)
    this.totalEarned.value = this.totalEarned.value + amount
  }

  @abimethod({ readonly: true })
  public get_stats(): uint64 {
    const calls: uint64 = this.totalCalls.value
    return calls
  }

  @abimethod()
  public withdraw(assetId: uint64): void {
    assert(Txn.sender === this.owner.value, 'Only owner can withdraw')

    const balance = this.totalEarned.value
    assert(balance > Uint64(0), 'No funds to withdraw')

    itxn.assetTransfer({
      xferAsset: assetId,
      assetReceiver: this.owner.value,
      assetAmount: balance,
      fee: Uint64(0)
    }).submit()

    this.totalEarned.value = Uint64(0)
  }
}
